arguments.command:
cd /tmp/vally-eval-trial-PfanNO && cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public sealed record CalculatePayableTotalQuery(string CustomerTier, decimal OrderSubtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotalQuery query) => query.OrderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/GoldCustomerCheckoutTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public sealed class GoldCustomerCheckoutTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var handler = new CalculatePayableTotalHandler();

        var payable = handler.Handle(new CalculatePayableTotalQuery("Gold", 100.00m));

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -vi "^\s*$" | tail -20

